-- Eternal Nights Animatronic Teleport Script
-- FIXED: Works for EVERY animatronic + Custom Speed 40

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LocalPlayer = Players.LocalPlayer

-- Settings
local DETECTION_RANGE = 20
local TELEPORT_COOLDOWN = 2
local CUSTOM_SPEED = 40 -- Your custom speed
local lastTeleportTime = 0

-- ALL animatronic names
local ANIMATRONICS = {
    "chica",
    "cupcake", 
    "puppet",
    "freddy",
    "golden freddy",
    "goldenfreddy",
    "foxy",
    "bonnie"
}

print("==========================================")
print("✅ SCRIPT LOADING...")
print("==========================================")

-- Set custom speed
local function setSpeed()
    local char = LocalPlayer.Character
    if char then
        local humanoid = char:FindFirstChildOfClass("Humanoid")
        if humanoid then
            humanoid.WalkSpeed = CUSTOM_SPEED
        end
    end
end

-- Check if name matches animatronic
local function isAnimatronic(name)
    local lowerName = string.lower(name)
    for _, animName in pairs(ANIMATRONICS) do
        if string.find(lowerName, animName) then
            return true
        end
    end
    return false
end

-- Search for animatronics
local function findAllAnimatronics()
    local found = {}
    
    local function searchFolder(parent, depth)
        if depth > 5 then return end
        
        for _, obj in pairs(parent:GetChildren()) do
            if obj:IsA("Model") and isAnimatronic(obj.Name) then
                table.insert(found, obj)
            end
            
            if obj:IsA("Folder") or obj:IsA("Model") then
                searchFolder(obj, depth + 1)
            end
        end
    end
    
    searchFolder(workspace, 0)
    return found
end

-- Check if player is alive
local function isPlayerAlive(player)
    if not player or not player.Character then return false end
    
    local humanoid = player.Character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return false end
    
    if humanoid.Health <= 0 then return false end
    
    local hrp = player.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end
    
    return true
end

-- Get ONE random ALIVE player
local function getAlivePlayer()
    local aliveList = {}
    
    for _, player in pairs(Players:GetPlayers()) do
        if player ~= LocalPlayer and isPlayerAlive(player) then
            table.insert(aliveList, player)
        end
    end
    
    if #aliveList > 0 then
        return aliveList[math.random(1, #aliveList)]
    end
    
    return nil
end

-- Teleport function
local function teleport(position)
    local char = LocalPlayer.Character
    if not char then return false end
    
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end
    
    -- Check if I'm alive before teleporting
    local myHumanoid = char:FindFirstChildOfClass("Humanoid")
    if not myHumanoid or myHumanoid.Health <= 0 then
        return false
    end
    
    -- Disable collisions
    for _, part in pairs(char:GetDescendants()) do
        if part:IsA("BasePart") then
            part.CanCollide = false
        end
    end
    
    -- Teleport
    local offset = Vector3.new(math.random(-5, 5), 2, math.random(-5, 5))
    hrp.CFrame = CFrame.new(position + offset)
    hrp.Velocity = Vector3.new(0, 0, 0)
    hrp.RotVelocity = Vector3.new(0, 0, 0)
    
    -- Re-enable collisions
    task.delay(0.5, function()
        if char and char.Parent then
            for _, part in pairs(char:GetDescendants()) do
                if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                    part.CanCollide = true
                end
            end
        end
    end)
    
    -- Reapply speed after teleport
    setSpeed()
    
    return true
end

-- Get closest threat info
local function getClosestThreat()
    local char = LocalPlayer.Character
    if not char then return nil, 999 end
    
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil, 999 end
    
    -- Check if I'm alive
    local myHumanoid = char:FindFirstChildOfClass("Humanoid")
    if not myHumanoid or myHumanoid.Health <= 0 then
        return nil, 999
    end
    
    local myPos = hrp.Position
    local animatronics = findAllAnimatronics()
    local closestDist = 999
    local closestName = "None"
    
    for _, obj in pairs(animatronics) do
        if obj and obj.Parent then
            local root = obj:FindFirstChild("HumanoidRootPart") or 
                        obj:FindFirstChild("Torso") or 
                        obj:FindFirstChild("Head") or
                        obj:FindFirstChild("UpperTorso") or
                        obj.PrimaryPart
            
            if root and root:IsA("BasePart") then
                local distance = (myPos - root.Position).Magnitude
                
                if distance < closestDist then
                    closestDist = distance
                    closestName = obj.Name
                end
            end
        end
    end
    
    return closestName, closestDist
end

-- Main detection function
local function checkThreats()
    local threatName, distance = getClosestThreat()
    
    -- Check if threat is within detection range AND cooldown has passed
    if distance <= DETECTION_RANGE then
        local currentTime = tick()
        
        -- Only teleport if cooldown has passed
        if currentTime - lastTeleportTime >= TELEPORT_COOLDOWN then
            print("🚨 " .. threatName .. " AT " .. math.floor(distance) .. " STUDS!")
            
            local target = getAlivePlayer()
            
            if target then
                local targetHRP = target.Character:FindFirstChild("HumanoidRootPart")
                if targetHRP then
                    if teleport(targetHRP.Position) then
                        print("✅ TELEPORTED TO: " .. target.Name)
                        lastTeleportTime = currentTime
                    else
                        print("❌ Teleport failed!")
                    end
                end
            else
                print("⚠️ NO ALIVE PLAYERS!")
            end
        end
    end
end

-- Main connection
local mainConnection
local speedConnection

local function setupConnection()
    if mainConnection then
        mainConnection:Disconnect()
    end
    if speedConnection then
        speedConnection:Disconnect()
    end
    
    mainConnection = RunService.Heartbeat:Connect(checkThreats)
    
    -- Constantly maintain speed
    speedConnection = RunService.Heartbeat:Connect(function()
        setSpeed()
    end)
end

-- Setup initially
wait(1) -- Wait for character to load
setSpeed()
setupConnection()

-- Reconnect after respawn
LocalPlayer.CharacterAdded:Connect(function(character)
    wait(1)
    lastTeleportTime = 0
    setSpeed()
    print("🔄 Respawned - Script active! Speed set to " .. CUSTOM_SPEED)
    setupConnection()
end)

-- Handle humanoid changes (in case game tries to reset speed)
if LocalPlayer.Character then
    local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
    if humanoid then
        humanoid:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
            if humanoid.WalkSpeed ~= CUSTOM_SPEED then
                humanoid.WalkSpeed = CUSTOM_SPEED
            end
        end)
    end
end

print("✅ SCRIPT LOADED!")
print("📏 Detection: " .. DETECTION_RANGE .. " studs")
print("⏱️ Cooldown: " .. TELEPORT_COOLDOWN .. " seconds")
print("🏃 Speed: " .. CUSTOM_SPEED)
print("♻️ Works after death")
print("🔄 Works for EVERY animatronic")
print("==========================================")

-- Debug
spawn(function()
    while wait(3) do
        local name, dist = getClosestThreat()
        if dist < 999 then
            local timeSince = math.floor(tick() - lastTeleportTime)
            print("👁️ " .. name .. ": " .. math.floor(dist) .. " studs | Last TP: " .. timeSince .. "s ago")
        end
    end
end)

